WITH store_agg AS ( SELECT ss_item_sk, SUM(ss_net_profit) AS store_net_profit, SUM(ss_quantity) AS store_quantity, SUM(ss_ext_discount_amt) AS store_discount, SUM(ss_ext_sales_price) AS store_sales FROM store_sales GROUP BY ss_item_sk ), web_agg AS ( SELECT ws_item_sk, SUM(ws_net_profit) AS web_net_profit, SUM(ws_quantity) AS web_quantity, SUM(ws_ext_discount_amt) AS web_discount, SUM(ws_ext_sales_price) AS web_sales FROM web_sales GROUP BY ws_item_sk ), web_warehouse_rank AS ( SELECT ws_item_sk, w_warehouse_name, warehouse_net_profit, ROW_NUMBER() OVER (PARTITION BY ws_item_sk ORDER BY warehouse_net_profit DESC) AS rn FROM ( SELECT ws.ws_item_sk, w.w_warehouse_name, SUM(ws.ws_net_profit) AS warehouse_net_profit FROM web_sales ws JOIN warehouse w ON ws.ws_warehouse_sk = w.w_warehouse_sk GROUP BY ws.ws_item_sk, w.w_warehouse_name ) sub ) SELECT i.i_item_id, i.i_product_name, i.i_brand, i.i_category, COALESCE(sa.store_net_profit, 0) + COALESCE(wa.web_net_profit, 0) AS total_net_profit, COALESCE(sa.store_quantity, 0) + COALESCE(wa.web_quantity, 0) AS total_quantity, CASE WHEN COALESCE(sa.store_discount, 0) + COALESCE(wa.web_discount, 0) > 0.30 * (COALESCE(sa.store_sales,0) + COALESCE(wa.web_sales,0)) THEN 'High Discount' WHEN COALESCE(sa.store_discount, 0) + COALESCE(wa.web_discount, 0) > 0.15 * (COALESCE(sa.store_sales,0) + COALESCE(wa.web_sales,0)) THEN 'Medium Discount' ELSE 'Low Discount' END AS discount_category, RANK() OVER (ORDER BY COALESCE(sa.store_net_profit, 0) + COALESCE(wa.web_net_profit, 0) DESC) AS profit_rank, wwr.w_warehouse_name AS top_warehouse_name FROM item i LEFT JOIN store_agg sa ON i.i_item_sk = sa.ss_item_sk LEFT JOIN web_agg wa ON i.i_item_sk = wa.ws_item_sk LEFT JOIN ( SELECT ws_item_sk, w_warehouse_name FROM web_warehouse_rank WHERE rn = 1 ) wwr ON i.i_item_sk = wwr.ws_item_sk WHERE i.i_category IS NOT NULL ORDER BY profit_rank LIMIT 20
